import { run, waitSignal, signal } from "zttp:durable";

// `waitSignal` returns a payload some separate `signal` call wrote, so its
// provenance is unknowable to the checker and the binding declares
// `unknown`. Reaching the response with that clears `no_secret_leakage`,
// `no_credential_leakage`, and `deterministic`, and `idempotent` follows
// determinism, so none of the four are on this list: the approval verdict
// here is a constant, not a read of the parked payload.
structural ApprovalProof<T> = Proof<T,
  | "retry_safe"
  | "post_only"
  | "state_isolated"
  | "result_safe"
  | "optional_safe"
  | "input_validated"
  | "pii_contained"
  | "injection_safe"
  | "canonical"
  | "cost_bounded"
>;

export function handler(req: Request): ApprovalProof<Response> {
  const key = req.headers.get("idempotency-key");
  if (key === undefined) {
    return Response.json({ error: "missing Idempotency-Key" }, { status: 400 });
  }
  if (req.method !== "POST") {
    return Response.json({ error: "method not allowed" }, { status: 405 });
